function loadAnalytics(token){if(!/^[a-f0-9]{32}$/.test(token||'')||navigator.doNotTrack==='1'||navigator.globalPrivacyControl)return;const s=document.createElement('script');s.defer=true;s.src='https://static.cloudflareinsights.com/beacon.min.js';s.dataset.cfBeacon=JSON.stringify({token,spa:false});document.head.append(s)}
let webcamStream=null;
async function openWebcam(){if(busy)return;try{webcamStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1920},height:{ideal:1080}},audio:false})}catch{toast('De camera is niet beschikbaar of er is geen toestemming gegeven. Kies een foto.');return}$('#webcamVideo').srcObject=webcamStream;$('#webcam').showModal()}
function closeWebcam(){webcamStream?.getTracks().forEach(t=>t.stop());webcamStream=null;$('#webcamVideo').srcObject=null;if($('#webcam').open)$('#webcam').close()}
$('#webcam').addEventListener('close',closeWebcam);$('#webcamCancel').onclick=closeWebcam;
$('#webcamCapture').onclick=()=>{const v=$('#webcamVideo');if(!v.videoWidth)return;const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(b=>{closeWebcam();if(b)choosePhoto(new File([b],'camera.jpg',{type:'image/jpeg'}))},'image/jpeg',0.92)};
// Trade mode: live camera scanning with an instant price and a running give/get total.
const trade={items:[],active:false,paused:false,stream:null,attempt:0,misses:0,current:null,lastId:'',lastAt:0};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const tradeCurrency=()=>markets[market].currency||'EUR';
const tmoney=(n,c)=>new Intl.NumberFormat(currentLocale(),{style:'currency',currency:c}).format(n);
function priceText(p){if(!p)return 'Geen prijs bekend';const cur=tradeCurrency(),local=p.currency===cur?null:convert(p.amount,p.currency,cur,rates);return tmoney(p.amount,p.currency)+(local?' (≈ '+tmoney(local,cur)+')':'')}
function tradeState(text,{busy=false,found=false}={}){$('#tradeStatus').textContent=text;$('#tradeDot').className='trade-dot'+(busy?' busy':'')+(found?' found':'')}
function stopTradeCamera(){trade.stream?.getTracks().forEach(t=>t.stop());trade.stream=null;$('#tradeVideo').srcObject=null}
function closeTrade(){trade.active=false;stopTradeCamera();if($('#trade').open)$('#trade').close()}
async function openTrade(){if(!ready){toast('Wacht tot de catalogus is geladen.');return}$('#trade').showModal();trade.active=true;trade.paused=false;trade.attempt=trade.misses=0;$('#tradeAttempt').textContent='';$('#tradeHint').hidden=true;$('#tradeResult').hidden=true;$('#tradeProgress').value=0;renderTrade();tradeState('Camera starten…',{busy:true});
 try{trade.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false})}catch{$('#tradeCamera').hidden=true;tradeState('De camera is niet beschikbaar of er is geen toestemming gegeven. Typ hieronder de naam en het nummer.');return}
 if(!trade.active){stopTradeCamera();return}
 $('#tradeCamera').hidden=false;$('#tradeVideo').srcObject=trade.stream;tradeState('Tekstherkenning laden. De eerste keer kan dit wat langer duren…',{busy:true});
 try{await getWorker()}catch{tradeState('Tekstherkenning kon niet worden geladen. Typ hieronder de naam en het nummer.');return}
 tradeLoop()}
async function tradeLoop(){while(trade.active){const v=$('#tradeVideo');if(trade.paused||busy||!v.videoWidth){await sleep(300);continue}
 busy=true;trade.attempt++;$('#tradeAttempt').textContent='Poging '+trade.attempt;$('#tradeProgress').value=0;ocrProgress=p=>{$('#tradeProgress').value=p};
 if(trade.misses<3)tradeState('Kaart zoeken… houd de kaart stil in het kader.',{busy:true});
 let text='';try{text=(await worker.recognize(ocrCanvas(v,v.videoWidth,v.videoHeight,trade.attempt%2?'bw':'gray'))).data.text||''}catch{}finally{busy=false}
 if(!trade.active||trade.paused)continue;
 const hits=matchCards(text,cards,sets,{limit:8}),hit=confident(hits);
 // The card just added is usually still in view; ignore it briefly so it isn't offered again.
 if(hit&&hit.card.id===trade.lastId&&Date.now()-trade.lastAt<5000){await sleep(250);continue}
 if(hit){trade.misses=0;$('#tradeHint').hidden=true;await showTradeResult(hit.card,hits.filter(h=>h!==hit))}
 else{trade.misses++;if(trade.misses>=3){$('#tradeHint').hidden=false;tradeState('Nog niet gevonden, ik blijf zoeken…',{busy:true})}if(hits.length)showCandidates(hits)}
 await sleep(250)}}
function showCandidates(hits){if(trade.current)return;const box=$('#tradeResult');box.hidden=false;box.innerHTML='<div class="trade-alts"><span>Bedoel je:</span></div>';const more=document.createElement('button');more.className='textbutton';more.textContent='Scan verder';more.onclick=resumeTrade;hits.slice(0,8).forEach(h=>{const b=document.createElement('button');b.className='outline';b.dataset.noTranslate='';b.textContent=h.card.name+' #'+h.card.localId+' · '+(sets[h.card.setId]?.name||h.card.setId)+(year(h.card.setId)?' · '+year(h.card.setId):'');b.onclick=()=>showTradeResult(h.card,[]);box.firstChild.append(b)});box.firstChild.append(more)}
async function showTradeResult(card,alts){trade.paused=true;trade.current={card,price:null};const s=sets[card.setId];tradeState('Gevonden! Prijs ophalen…',{busy:true,found:true});$('#tradeProgress').value=1;
 const box=$('#tradeResult');box.hidden=false;box.innerHTML=pic({...card,lang:language})+'<div class="trade-meta"><strong data-no-translate>'+escape(card.name)+'</strong><span data-no-translate>'+escape(s?.name||card.setId)+(year(card.setId)?' · '+year(card.setId):'')+' · #'+escape(card.localId)+'</span><span class="trade-price" id="tradePrice">…</span><small id="tradeSource"></small></div><div class="scan-tools"><button class="primary" data-side="get">+ Ik krijg</button><button class="outline" data-side="give">+ Ik geef</button><button class="textbutton" id="tradeNext">Scan volgende</button></div>'+(alts.length?'<div class="trade-alts"><span>Niet deze?</span></div>':'');
 protectImage(box);alts.slice(0,3).forEach(h=>{const b=document.createElement('button');b.className='outline';b.dataset.noTranslate='';b.textContent=h.card.name+' #'+h.card.localId+' · '+(sets[h.card.setId]?.name||h.card.setId)+(year(h.card.setId)?' · '+year(h.card.setId):'');b.onclick=()=>showTradeResult(h.card,[]);box.querySelector('.trade-alts').append(b)});
 box.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>addTrade(b.dataset.side));$('#tradeNext').onclick=resumeTrade;
 const ticket=card.id;let price=null;try{price=headlinePrice((await getJSON('https://api.tcgdex.net/v2/'+language+'/cards/'+encodeURIComponent(card.id))).pricing,markets[market].prefer)}catch{}
 if(trade.current?.card.id!==ticket)return;trade.current.price=price;$('#tradePrice').textContent=priceText(price);$('#tradeSource').textContent=price?price.source+(price.variant?' · '+price.variant:''):'';tradeState('Gevonden: '+card.name+'. Voeg toe of scan de volgende kaart.',{found:true})}
function resumeTrade(){trade.current=null;trade.paused=false;trade.misses=0;$('#tradeResult').hidden=true;$('#tradeHint').hidden=true;if(!trade.stream)tradeState('Typ hieronder de naam en het nummer.')}
function addTrade(side){if(!trade.current)return;trade.items.push({...trade.current,side});trade.lastId=trade.current.card.id;trade.lastAt=Date.now();renderTrade();resumeTrade()}
function renderTrade(){const cur=tradeCurrency(),t=tradeTotals(trade.items,cur,rates);for(const side of ['give','get']){const ul=$(side==='give'?'#tradeGive':'#tradeGet');ul.replaceChildren();trade.items.forEach((item,i)=>{if(item.side!==side)return;const li=document.createElement('li');li.innerHTML='<span data-no-translate>'+escape(item.card.name)+' #'+escape(item.card.localId)+'</span><span>'+escape(priceText(item.price))+'</span>';const x=document.createElement('button');x.textContent='✕';x.setAttribute('aria-label','Verwijder '+item.card.name);x.onclick=()=>{trade.items.splice(i,1);renderTrade()};li.append(x);ul.append(li)})}
 $('#tradeGiveTotal').textContent=tmoney(t.give,cur);$('#tradeGetTotal').textContent=tmoney(t.get,cur);
 $('#tradeBalance').textContent=!trade.items.length?'':(t.diff>0?'Je krijgt meer waarde: '+tmoney(t.diff,cur):t.diff<0?'Je geeft meer waarde: '+tmoney(-t.diff,cur):'Gelijke ruil')+(t.skipped?' · '+t.skipped+' niet meegeteld (geen prijs of koers)':'')}
$('#openTrade').onclick=openTrade;$('#tradeClose').onclick=closeTrade;$('#trade').addEventListener('close',closeTrade);
$('#tradeClear').onclick=()=>{trade.items=[];renderTrade()};
$('#tradeSearch').onsubmit=e=>{e.preventDefault();const q=$('#tradeQuery').value.trim();if(!q||!ready)return;const hits=matchCards(q,cards,sets,{limit:8}),hit=confident(hits)||(hits.length===1?hits[0]:null);trade.current=null;if(hit)showTradeResult(hit.card,hits.filter(h=>h!==hit));else if(hits.length){trade.paused=true;showCandidates(hits)}else tradeState('Geen kaart gevonden voor deze tekst.')};

document.addEventListener('interface-language-change',()=>{render()});
